  });

  it('rejects malformed thresholds', () => {
    expect(() => parseThresholds(['exact_match'])).toThrow('Malformed threshold');
    expect(() => parseThresholds(['exact_match=not_a_number'])).toThrow('not a valid number');
  });

  it('rejects out-of-range threshold values', () => {
    expect(() => parseThresholds(['exact_match=-0.1'])).toThrow('outside valid range');
    expect(() => parseThresholds(['exact_match=1.1'])).toThrow('outside valid range');
  });

  it('validates thresholds against evaluations', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const valid = validateThresholds({ exact_match: 0.5 }, evaluations);
    expect(valid.valid).toBe(true);

    const invalid = validateThresholds({ unknown_metric: 0.5 }, evaluations);
    expect(invalid.valid).toBe(false);
    expect(invalid.error).toContain('Unknown metric id: unknown_metric');
    expect(invalid.error).toContain('exact_match');
  });

  it('checks thresholds against metric scores', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });
    const result = checkThresholds({ exact_match: 0.5, toxicity: 0.99 }, evaluations);
    expect(result.passed).toBe(true);
    expect(result.results).toHaveLength(2);
    expect(result.results[0]).toMatchObject({
      metric: 'exact_match',
      min: 0.5,
      passed: true
    });
  });

  it('fails threshold when score is too low', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['world']
    });
    const result = checkThresholds({ exact_match: 0.9 }, evaluations);
    expect(result.passed).toBe(false);
    expect(result.results[0].passed).toBe(false);
  });

  it('handles metrics with null scores', () => {
    const evaluations = runEvaluations({
      outputs: [],
      references: []
    });
    const result = checkThresholds({ exact_match: 0.5 }, evaluations);
    expect(result.passed).toBe(false);
    expect(result.results[0].passed).toBe(false);
    expect(result.results[0].score).toBe(null);
  });

  it('includes thresholds in generated report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.9, toxicity: 0.99 },
      generatedAt: '2024-01-01T00:00:00.000Z'
    });
    expect(report.passed).toBe(true);
    expect(report.thresholds).toHaveLength(2);
    expect(report.thresholds[0]).toMatchObject({
      metric: 'exact_match',
      min: 0.9,
      passed: true
    });
  });

  it('marks report as failed when threshold fails', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['world']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.9 },
      generatedAt: '2024-01-01T00:00:00.000Z'
    });
    expect(report.passed).toBe(false);
  });

  it('does not include thresholds when none provided', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z'
    });
    expect(report.passed).toBeUndefined();
    expect(report.thresholds).toBeUndefined();
  });
});

