16	export function parseThresholds(thresholdStrings = []) {
17	  const thresholds = {};
18	  for (const str of thresholdStrings) {
19	    const match = str.match(/^([^=]+)=([^=]+)$/);
20	    if (!match) {
21	      throw new Error(`Malformed threshold: "${str}". Expected format: <metric>=<number>`);
22	    }
23	    const [, metric, valueStr] = match;
24	    const value = Number.parseFloat(valueStr);
25	    if (Number.isNaN(value)) {
26	      throw new Error(`Invalid threshold value for "${metric}": "${valueStr}" is not a valid number`);
27	    }
28	    if (value < 0 || value > 1) {
29	      throw new Error(`Invalid threshold value for "${metric}": ${value} is outside valid range [0, 1]`);
30	    }
31	    thresholds[metric] = value;
32	  }
33	  return thresholds;
34	}
35	
36	export function validateThresholds(thresholds, evaluations) {
37	  if (!thresholds || Object.keys(thresholds).length === 0) {
38	    return { valid: true };
39	  }
40	
41	  const metricIds = new Set(evaluations.map((m) => m.id));
42	  const unknownMetrics = Object.keys(thresholds).filter((metric) => !metricIds.has(metric));
43	
44	  if (unknownMetrics.length > 0) {
45	    const validMetrics = Array.from(metricIds).sort();
46	    return {
47	      valid: false,
48	      error: `Unknown metric id: ${unknownMetrics[0]}. Valid metric ids: ${validMetrics.join(', ')}`
49	    };
50	  }
51	
52	  return { valid: true };
